"""Package readable metadata and code after the numerical completion receipt."""
from pathlib import Path
import json,csv,shutil,hashlib,sys,html
R=Path(__file__).resolve().parents[2]
run=Path(sys.argv[1]); done=json.loads((run/'COMPLETE.json').read_text())
assert done['status']=='passed_structural_and_source_preservation'
for sub in ['contracts','dag','code','scripts','examples']:
 dest=run/('metadata' if sub=='contracts' else sub);dest.mkdir(exist_ok=True)
 for src in (R/'downstream'/sub).rglob('*'):
  if not src.is_file() or '__pycache__' in src.parts:continue
  target=dest/src.relative_to(R/'downstream'/sub);target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,target)
for name in ['README.md','SCHEMA.md','local_paths.example.do']:
 shutil.copyfile(R/'downstream'/name,run/name)
shutil.copyfile(R/'downstream/00_MASTER.do',run/'code/00_MASTER_SOURCE.do')
(run/'00_MASTER.do').write_text('* Rebuild from configured repository sources into a NEW run folder.\n'+'do "'+str(R/'downstream/00_MASTER.do')+'" "'+str(R)+'"\n')
# Top-level master is a working launcher; code/ contains the source snapshot.
(run/'CODE-LOCATION.md').write_text('Rebuild entry: '+str(R/'downstream/00_MASTER.do')+'\n\n00_MASTER.do is the working owner launcher into the configured repository. code/00_MASTER_SOURCE.do preserves the original controller for provenance. Do not run the snapshot independently of repository setup.\n')
with (run/'metadata/dictionary_development.csv').open() as f:rows=list(csv.DictReader(f))
core={'obs_id','firm_id','year','province_code','district_code','industry_code','dataset_mode','panel_id_synthetic','workers','gross_output_nominal','value_added_nominal','va_signed_nominal','intermediate_inputs_nominal','capital_stock_nominal','capital_additions_nominal','export_share_pct','import_value_nominal','foreign_ownership_pct','total_gj_s1','co2_total_s1','dev_nominal_tfp_op','dev_nominal_tfp_lp','dev_nominal_tfp_acf','dev_nominal_tfp_wrdg'}
trs=''.join('<tr data-core="'+str(int(x['variable'] in core))+'"><td><code>'+html.escape(x['variable'])+'</code></td><td>'+html.escape(x['label'])+'</td><td>'+html.escape(x['storage'])+'</td><td>'+html.escape(x['nonmissing'])+'</td></tr>' for x in rows)
page='''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dataset G0 → G0.5 → G1</title><style>body{font:16px system-ui;margin:0;background:#f5f4ef;color:#172d3e}main{max-width:1100px;margin:auto;padding:36px}h1{font-size:36px;margin:10px 0}p{line-height:1.6}a{color:#126786}section{background:white;padding:24px;margin:20px 0;border-radius:10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.tag{color:#5c694a;font-weight:700}button,input{font:inherit;padding:10px;border:1px solid #bdc8cb;border-radius:5px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{text-align:left;border-bottom:1px solid #dce2e1;padding:10px}code{font-size:13px} .notice{background:#fff0cf;padding:16px;border-left:4px solid #b67913}@media(max-width:700px){.grid{display:block}main{padding:18px}table{font-size:13px}}</style><main><div class="tag">G0 / G0.5 / G1 · 16 September 2026</div><h1>Dataset untuk downstream</h1><p>33.049 baris × 515 kolom dalam setiap file. Dua mode dengan nama variabel yang sama, 12 tahun kalender, nilai sumber tetap, dan hasil G1 tersimpan.</p><div class="grid"><section><h2>Panel development</h2><p>10.395 ID perusahaan fiktif. Perturbed values dan hasil G1 nominal; siap untuk pengembangan kode panel.</p><p><a href="data/panel_development.dta">panel_development.dta</a> · <a href="01_OPEN_DEVELOPMENT.do">Buka di Stata</a></p></section><section><h2>Data actual</h2><p>Observasi–tahun dari G0. firm_id kosong karena linkage perusahaan belum terverifikasi. Tidak memuat hasil G1 dummy.</p><p><a href="data/analysis_actual.dta">analysis_actual.dta</a> · <a href="02_OPEN_ACTUAL.do">Buka di Stata</a></p></section></div><div class="notice"><b>Belum semua analisis empiris siap.</b> Kabupaten kosong; tahun 2016 tidak ada; concordance industri, ID real dan deflator/measurement admission masih diperlukan. Nilai TFP G1 adalah residual nominal development.</div><section><h2>Alur pembentukan</h2><p>Master G0 / master G1 → pin sumber → pilih field → kunci dan dimensi → samakan schema → bandingkan semua nilai sumber → cocokkan G1 N06 → validasi dan paket.</p><p><a href="dag/DAG.md">DAG lengkap</a> · <a href="SCHEMA.md">Kontrak dataset</a> · <a href="reports/readiness.csv">Kesiapan analisis</a> · <a href="COMPLETE.json">Bukti build</a></p><p><a href="metadata/downstream_plans.csv">44 rencana penelitian</a> · <a href="metadata/variable_year_evidence.csv">Bukti definisi/unit per tahun</a> · <a href="metadata/full_source_catalogue.csv">Katalog seluruh kolom master sumber</a></p></section><section><h2>Kolom dataset</h2><p>Tabel menampilkan jumlah nilai terisi pada development. Jumlah terisi bukan ukuran kesiapan empiris; status unit, cakupan, dan definisi tetap berlaku.</p><input id="q" placeholder="Cari variabel atau definisi…" aria-label="Cari variabel"><label><input type="checkbox" id="all"> Tampilkan semua kolom</label><table><thead><tr><th>Variabel</th><th>Label</th><th>Tipe</th><th>Terisi / 33.049</th></tr></thead><tbody>'''+trs+'''</tbody></table></section><script>const q=document.querySelector('#q'),a=document.querySelector('#all');function filter(){const s=q.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!(r.textContent.toLowerCase().includes(s)&&(s||a.checked||r.dataset.core==='1')))}q.addEventListener('input',filter);a.addEventListener('change',filter);filter()</script></main></html>'''
(run/'00_START_HERE.html').write_text(page)
# Every local href must be an existing deliverable; no stale relative paths.
import re
for href in re.findall(r'href="([^"]+)"',page):assert (run/href).exists(),href
files=[]
for p in run.rglob('*'):
 if not p.is_file() or p.name.startswith('._') or p.name in ['HANDOFF.json'] or p.suffix=='.dta':continue
 files.append({'path':str(p.relative_to(run)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(run/'HANDOFF.json').write_text(json.dumps({'numerical_receipt':'COMPLETE.json','documentation_and_code_snapshot':files,'scope':'Native outputs verified; no universal empirical-readiness claim'},indent=2)+'\n')
print('HANDOFF READY',run)
